{{-- Cláusula: DISPOSITIVO GPS, ENTREGA DE CREDENCIALES Y EJECUCION POR DESACTIVACIÓN.
     Fuente: modelo a.1 (NOVENO), verbatim. El número de WhatsApp sale de
     $vm->constante('whatsapp_gps'); la referencia a la cláusula de ejecución
     via $vm->ord->de('ejecucion'). Solo se incluye cuando $vm->gps.

     CON DOS BIENES (redacción 2, 19/11/2026) sigue a la maestra de su
     combinación — $vm->segunBienes(), igual que la cláusula de ejecución. La
     de futuro + presente (a.x.5) trae además dos giros propios: el costo es
     "DE SU CARGO" y el acreedor puede proceder "DE FORMA INMEDIATA". --}}
@php
    $n = $vm->ord->numero('gps');
    $i = 0;
    $b = fn (string $uno, string|array $dos) => $vm->segunBienes($uno, $dos);
    // "SE ENCUENTRA EQUIPADO" queda en singular en las maestras de dos presentes y de dos
    // futuros (sic); concuerda en las de futuro + presente y en las dos de empresa con
    // dos futuros (a.4.3 / a.4.3.1).
    $gpsEquipados = 'LOS VEHICULOS DADOS EN GARANTÍA SE ENCUENTRAN EQUIPADOS';
    $gpsEquipadoSic = 'LOS VEHICULOS DADOS EN GARANTÍA SE ENCUENTRA EQUIPADO';
    $gpsEquipado = $b('EL VEHÍCULO DADO EN GARANTÍA SE ENCUENTRA EQUIPADO', [
        'presentes' => $gpsEquipadoSic,
        'futuros' => $vm->esJuridica() ? $gpsEquipados : $gpsEquipadoSic,
        'mixto' => $gpsEquipados,
    ]);
@endphp
<div class="clausula">
    <div class="clausula-titulo">{{ $vm->ord->de('gps') }}: DISPOSITIVO GPS, ENTREGA DE CREDENCIALES Y EJECUCION POR DESACTIVACIÓN.</div>
    <div class="numerales">
        <div class="numeral">{{ $n }}.{{ ++$i }}. {{ $vm->g->deudor() }} {{ $vm->g->verbo('DECLARA', 'DECLARAN') }} Y {{ $vm->g->verbo('GARANTIZA', 'GARANTIZAN') }} QUE {{ $gpsEquipado }} CON UN DISPOSITIVO DE GEOLOCALIZACIÓN (GPS) OPERATIVO, CUYA INSTALACIÓN, MANTENIMIENTO Y COSTO SERÁN EXCLUSIVAMENTE {{ $b('A', ['mixto' => 'DE']) }} SU CARGO DURANTE TODA LA VIGENCIA DE LA GARANTÍA.</div>
        <div class="numeral">{{ $n }}.{{ ++$i }}. EN EL ACTO DE LA SUSCRIPCIÓN DEL PRESENTE CONTRATO, {{ $vm->g->deudor() }} {{ $vm->g->verbo('ENTREGARÁ', 'ENTREGARÁN') }} A EL ACREEDOR, DE FORMA FEHACIENTE, EL NOMBRE DE USUARIO (USUARIO) Y LA CONTRASEÑA (CLAVE) DE ACCESO AL SISTEMA DE MONITOREO DEL GPS {{ $b('DEL VEHÍCULO GARANTIZADO', ['presentes' => 'DE LOS VEHICULOS GARANTIZADO', 'futuros' => 'DE LOS VEHICULOS GARANTIZADO', 'mixto' => 'DE LOS VEHICULOS GARANTIZADOS']) }}, ASÍ COMO TODA INFORMACIÓN NECESARIA PARA EL ACCESO REMOTO INMEDIATO Y PERMANENTE A LA UBICACIÓN Y ESTADO {{ $b('DEL BIEN', 'DE LOS BIENES') }} (EN ADELANTE, LAS “CREDENCIALES”). ASIMISMO, {{ $vm->g->deudor() }} SE {{ $vm->g->verbo('OBLIGA', 'OBLIGAN') }} A NOTIFICAR POR ESCRITO Y CON CARÁCTER PREVIO CUALQUIER CAMBIO DE DICHAS CREDENCIALES AL NÚMERO DE WHATSAPP {{ $vm->constante('whatsapp_gps') }}, SUMINISTRANDO A EL ACREEDOR LAS NUEVAS CREDENCIALES DENTRO DE LAS DOCE (12) HORAS SIGUIENTES AL CAMBIO.</div>
        <div class="numeral">{{ $n }}.{{ ++$i }}. {{ $vm->g->deudor() }} SE {{ $vm->g->verbo('OBLIGA', 'OBLIGAN') }} A MANTENER EL DISPOSITIVO GPS DEBIDAMENTE ENCENDIDO, ACTIVO, CON SERVICIO DE DATOS Y EN PERFECTO ESTADO DE FUNCIONAMIENTO, Y A NO INTERFERIR, MANIPULAR, DESACTIVAR, OCULTAR, RETIRAR O ALTERAR EN FORMA ALGUNA EL REFERIDO DISPOSITIVO O SU SISTEMA DE COMUNICACIÓN, NI A IMPEDIR EL ACCESO REMOTO POR PARTE DE EL ACREEDOR A LA INFORMACIÓN QUE EL MISMO SUMINISTRE.</div>
        <div class="numeral">{{ $n }}.{{ ++$i }}. EN CASO {{ $vm->g->deudor() }} {{ $vm->g->verbo('DESACTIVE', 'DESACTIVEN') }}, {{ $vm->g->verbo('MANIPULE', 'MANIPULEN') }}, O {{ $vm->g->verbo('INTERRUMPA', 'INTERRUMPAN') }} VOLUNTARIA O NEGLIGENTEMENTE EL FUNCIONAMIENTO DEL GPS, {{ $vm->g->verbo('CANCELE', 'CANCELEN') }} EL SERVICIO DE DATOS, {{ $vm->g->verbo('CAMBIE', 'CAMBIEN') }}, O SE {{ $vm->g->verbo('NIEGUE', 'NIEGUEN') }} A PROPORCIONAR O {{ $vm->g->verbo('ACTUALICE', 'ACTUALICEN') }} LAS CREDENCIALES, O DE CUALQUIER FORMA IMPIDA EL ACCESO O LA CORRECTA GEOLOCALIZACIÓN {{ $b('DEL VEHÍCULO', ['presentes' => 'DE LOS VEHICULOS', 'futuros' => 'DE LOS VEHICULOS']) }}, DICHA CONDUCTA CONSTITUIRÁ INCUMPLIMIENTO GRAVE DEL PRESENTE CONTRATO Y SERÁ CONSIDERADA MOTIVO SUFICIENTE Y AUTOMÁTICO PARA QUE EL ACREEDOR, SIN NECESIDAD DE JUDICIALIZACIÓN PREVIA Y SIN PERJUICIO DE LAS DEMÁS ACCIONES QUE LE ASISTIEREN, PUEDA {{ $b('PROCEDER', ['mixto' => 'PROCEDER DE FORMA INMEDIATA']) }} A LA EJECUCIÓN DE LA GARANTÍA MOBILIARIA CONFORME SE SEÑALA EN LA CLAUSULA {{ $vm->ord->deF('ejecucion') }} DEL PRESENTE CONTRATO Y A LAS NORMAS APLICABLES, INCLUYENDO LA VENTA EXTRAJUDICIAL O LA ADJUDICACIÓN {{ $b('DEL BIEN', 'DE LOS BIENES') }}.</div>
    </div>
