    <div class="numerales">
        <div class="numeral">{{ $n }}.{{ ++$i }}. EN CASO DE LA HIPÓTESIS PREVISTA EN EL NUMERAL PRECEDENTE, EL ACREEDOR PODRÁ, A SU ELECCIÓN, Y SIN NECESIDAD AUTORIZACIÓN JUDICIAL CONSIDERAR VENCIDAS LAS OBLIGACIONES RESTANTES Y DISPONER DE LA VENTA EXTRAJUDICIAL O ADJUDICACIÓN {{ $b('DEL VEHÍCULO', ['presentes' => 'DE LOS VEHICULOS', 'futuros' => 'DE LOS VEHICULOS']) }}.</div>
        <div class="numeral">{{ $n }}.{{ ++$i }}. {{ $vm->g->deudor() }} {{ $vm->g->verbo('AUTORIZA', 'AUTORIZAN') }} DE FORMA EXPRESA E IRREVOCABLE A EL ACREEDOR A ACCEDER CON LAS CREDENCIALES ENTREGADAS A LA CUENTA DEL GPS, A VISUALIZAR LA UBICACIÓN Y ESTADO {{ $b('DEL VEHÍCULO', 'DE LOS VEHICULOS') }} Y A REALIZAR LAS GESTIONES NECESARIAS PARA SU LOCALIZACIÓN Y RECUPERACIÓN EN CASO DE MORA O INCUMPLIMIENTO. ASIMISMO, {{ $vm->g->deudor() }} {{ $vm->g->verbo('AUTORIZA', 'AUTORIZAN') }} AL ACREEDOR A SUMINISTRAR DICHAS CREDENCIALES A AUTORIDADES COMPETENTES O A TERCEROS CONTRATADOS POR EL ACREEDOR CUANDO ELLO SEA NECESARIO PARA LA EJECUCIÓN, RECUPERACIÓN O PROTECCIÓN {{ $b('DEL BIEN', 'DE LOS BIENES') }}.</div>
        <div class="numeral">{{ $n }}.{{ ++$i }}. EL ACREEDOR SE OBLIGA A UTILIZAR LAS CREDENCIALES ÚNICAMENTE PARA LOS FINES PREVISTOS EN EL PRESENTE CONTRATO Y A GUARDAR LA DEBIDA RESERVA SOBRE LOS DATOS PERSONALES A QUE TUVIERA ACCESO, SIN PERJUICIO DE LAS FACULTADES DE INFORMACIÓN Y REPORTE QUE LE IMPONGAN LAS NORMAS APLICABLES.</div>
        <div class="numeral">{{ $n }}.{{ ++$i }}. UNA VEZ EXTINGUIDA LA OBLIGACIÓN GARANTIZADA Y CANCELADA LA INSCRIPCIÓN EN EL SIGM, {{ $vm->g->deudor() }} {{ $vm->g->verbo('QUEDA', 'QUEDAN') }} {{ $vm->g->flex('FACULTADO') }} A REALIZAR EL CAMBIO DE CONTRASEÑA O A DEJAR SIN EFECTO EL ACCESO POR PARTE DE EL ACREEDOR.</div>
